-- TNYPL Season 1 Production Database Upgrade
create extension if not exists pgcrypto;
create table if not exists public.franchises(slug text primary key,name text not null,owner_name text not null,starting_points integer not null default 1000,points_spent integer not null default 0,squad_limit integer not null default 13,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
insert into public.franchises(slug,name,owner_name) values
('chennai-strikers','Chennai Strikers','Vimalesh Vedachalam'),('kovai-kings','Kovai Kings','Gopi Ramadoss'),('karaikudi-kings','Karaikudi Kings','Porkai Pandian Gopalakrishnan'),('trichy-titans','Trichy Titans','Satish Raja'),('tiruppur-blazers','Tiruppur Blazers','P. C. Binny Jo'),('nellai-falcons','Nellai Falcons','Ramanathan Periyaraja'),('thanjavur-royals','Thanjavur Royals','Saravanan Narasimhan & Santhana Krishnan'),('franchise-08','Franchise 08','Pending Confirmation') on conflict(slug) do update set name=excluded.name,owner_name=excluded.owner_name,updated_at=now();
create table if not exists public.league_settings(key text primary key,value text,updated_at timestamptz not null default now());
insert into public.league_settings(key,value) values('franchise_count','8'),('draft_date','2026-08-25'),('season_label','Season 1 – Inaugural Edition'),('league_status','Registration Open') on conflict(key) do update set value=excluded.value,updated_at=now();
alter table if exists public.players add column if not exists correction_notes text,add column if not exists payment_status text not null default 'pending',add column if not exists age_verification_status text not null default 'pending',add column if not exists status text not null default 'pending',add column if not exists draft_status text not null default 'not_eligible_yet',add column if not exists draft_category text,add column if not exists starting_points integer not null default 0,add column if not exists verified_at timestamptz,add column if not exists verified_by uuid,add column if not exists profile_photo_path text,add column if not exists profile_photo_public_url text,add column if not exists media_consent boolean not null default false;
-- Create owner assignment table after Auth users are invited.
create table if not exists public.franchise_owner_assignments(id bigint generated by default as identity primary key,user_id uuid not null unique references auth.users(id) on delete cascade,franchise_slug text not null references public.franchises(slug) on update cascade,franchise_name text not null,owner_name text not null,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.franchise_owner_assignments drop constraint if exists franchise_owner_assignments_franchise_slug_key;
create index if not exists franchise_owner_assignments_slug_idx on public.franchise_owner_assignments(franchise_slug);
-- Owner mappings: safe to rerun after users exist in Authentication.
with owners(email,slug,franchise,owner) as (values('vim22veda@gmail.com','chennai-strikers','Chennai Strikers','Vimalesh Vedachalam'),('Gopiramadoss@gmail.com','kovai-kings','Kovai Kings','Gopi Ramadoss'),('porkai@cakepoint.in','karaikudi-kings','Karaikudi Kings','Porkai Pandian Gopalakrishnan'),('Satishraja1509@gmail.com','trichy-titans','Trichy Titans','Satish Raja'),('binny.jo@rediffmail.com','tiruppur-blazers','Tiruppur Blazers','P. C. Binny Jo'),('rohan.ramanathan@gmail.com','nellai-falcons','Nellai Falcons','Ramanathan Periyaraja'),('saravanannarasimhan@gmail.com','thanjavur-royals','Thanjavur Royals','Saravanan Narasimhan'),('Santhanakrishnan1982@gmail.com','thanjavur-royals','Thanjavur Royals','Santhana Krishnan')) insert into public.franchise_owner_assignments(user_id,franchise_slug,franchise_name,owner_name) select u.id,o.slug,o.franchise,o.owner from owners o join auth.users u on lower(u.email)=lower(o.email) on conflict(user_id) do update set franchise_slug=excluded.franchise_slug,franchise_name=excluded.franchise_name,owner_name=excluded.owner_name,is_active=true,updated_at=now();
select slug,name,owner_name from public.franchises order by name;
